<?php require_once '../includes/functions.php'; require_role(['Admin','Departmental Admin']); $id=(int)($_GET['id']??0); if(!$id) die('Invalid request.'); $s=$pdo->prepare('SELECT * FROM book_entries WHERE id=?'); $s->execute([$id]); $r=$s->fetch(); if(!$r) die('Not found'); $fields=field_map(); $msg=''; if($_SERVER['REQUEST_METHOD']=='POST'){ foreach($fields as $k=>$label){ $new=$_POST[$k]??null; if((string)$new !== (string)$r[$k]){ $pdo->prepare('INSERT INTO entry_modification_logs(entry_id,modified_by,field_name,old_value,new_value) VALUES(?,?,?,?,?)')->execute([$id,$_SESSION['user_id'],$label,$r[$k],$new]); }} $sets=implode(',', array_map(fn($c)=>"$c=?", array_keys($fields))); $vals=[]; foreach(array_keys($fields) as $k) $vals[]=$_POST[$k]??null; $vals[]=$_SESSION['user_id']; $vals[]=$id; $pdo->prepare("UPDATE book_entries SET $sets,last_modified_by=?,last_modified_at=NOW() WHERE id=?")->execute($vals); redirect('view.php?id='.$id); } include '../includes/header.php'; ?>
<div class="card"><h2>Edit Entry</h2><form method="post"><div class="form-grid"><?php foreach($fields as $name=>$label): ?><div><label><?=e($label)?></label><?php if($name=='bibliography_note'): ?><textarea name="<?=$name?>"><?=e($r[$name])?></textarea><?php else: ?><input name="<?=$name?>" value="<?=e($r[$name])?>"><?php endif; ?></div><?php endforeach; ?></div><br><button class="btn">Update Entry</button></form></div>
